using System;

namespace Test
{
    public class Program
    {
        enum E
        {
            Zero,
            FortyTwo = 42
        };

        public static void Main()
        {
            E[] a = new[] { E.FortyTwo, 0 }; // Dev10 error CS0826
            Console.WriteLine(String.Format("Type={0}, a[0]={1}, a[1]={2}", a.GetType(), a[0], a[1]));
        }
    }
}

